const KYOKUSEI_KINS = new Set([10,30,50,55,75,95,115,120,140,160,180,185,205,225,245,250]);
const KAKUCHO_KINS  = new Set([19,38,57,76,114,133,152,171,190,209,228,247]);
const KURO_KINS     = new Set([1,20,22,39,43,50,51,58,64,69,72,77,85,88,93,96,106,107,108,109,110,111,112,113,114,115,146,147,148,149,150,151,152,153,154,155,165,168,173,176,184,189,192,197,203,210,211,218,222,239,241,260]);

const SEAL_NAMES = {1:'赤い龍',2:'白い風',3:'青い夜',4:'黄色い種',5:'赤い蛇',6:'白い世界の橋渡し',7:'青い手',8:'黄色い星',9:'赤い月',10:'白い犬',11:'青い猿',12:'黄色い人',13:'赤い空歩く人',14:'白い魔法使い',15:'青い鷲',16:'黄色い戦士',17:'赤い地球',18:'白い鏡',19:'青い嵐',20:'黄色い太陽'};

function sealName(n) { return SEAL_NAMES[n]; }
function antipodeSeal(n) { return ((n - 1 + 10) % 20) + 1; }
function analogSeal(n)   { return (38 - n) % 20 + 1; }
function occultSeal(n)   { return 21 - n; }

function calcKin(year, month, day) {
  const base = KINDATE[year]?.[month - 1];
  if (base == null) return null;
  let kin = (base + day) % 260;
  if (kin === 0) kin = 260;
  return kin;
}

function harmonicGroup(kin) {
  const start = kin - ((kin - 1) % 4);
  return [start, start + 1, start + 2, start + 3];
}

function toneRelations(tone) {
  // 倍音: pair-tone summing to 11, then ".13"
  const partner = 11 - tone;
  const baionPartner = (partner >= 1 && partner <= 10) ? partner : tone;
  const baion = `${baionPartner}.13`;
  // 補完: 14 - tone
  const hokan = 14 - tone;
  // 協和: tones 4 apart (paired 1.5, 2.6, 3.7, 4.8, 6.10, 7.11, 8.12, 9.13)
  let k1, k2;
  if (tone <= 6) { k1 = tone; k2 = tone + 4; }
  else { k1 = tone - 4; k2 = tone; }
  const kyowa = `${k1}.${k2}`;
  return { baion, hokan, kyowa };
}

function calcAge(year, month, day, today = new Date()) {
  let years  = today.getFullYear() - year;
  let months = today.getMonth() + 1 - month;
  if (today.getDate() < day) months--;
  if (months < 0) { years--; months += 12; }
  if (years < 0) { years = 0; months = 0; }
  return { years, months };
}

function getKinData(kin) {
  if (!kin || kin < 1 || kin > 260) return null;
  const d = TZOLKIN[kin];
  const sn = d.n;
  const waveKin = Math.floor((kin - 1) / 13) * 13 + 1;
  const wsn = TZOLKIN[waveKin].n;
  const mirror = 261 - kin;
  return {
    kin,
    solar_seal:         d.s,
    wavespell:          d.w,
    tone:               d.t,
    iching:             d.i,
    chakra1:            d.c1,
    chakra2:            d.c2,
    seal_no:            sn,
    guide:              d.g,
    is_kuro:            KURO_KINS.has(kin),
    mirror_kin:         mirror,
    absolute_opposite:  ((kin - 1 + 130) % 260) + 1,
    hannoh_no:  antipodeSeal(sn), hannoh: sealName(antipodeSeal(sn)),
    ruiji_no:   analogSeal(sn),   ruiji:  sealName(analogSeal(sn)),
    shinpi_no:  occultSeal(sn),   shinpi: sealName(occultSeal(sn)),
    w_hannoh:   sealName(antipodeSeal(wsn)),
    w_ruiji:    sealName(analogSeal(wsn)),
    w_shinpi:   sealName(occultSeal(wsn)),
    harmonic:        harmonicGroup(kin),
    mirror_harmonic: harmonicGroup(mirror),
    tone_relations:  toneRelations(d.t),
  };
}

function getNenpyoRows(birthYear, birthMonth, birthDay, count = 52) {
  const baseKin = calcKin(birthYear, birthMonth, birthDay);
  if (!baseKin) return [];
  const rows = [];
  let kin = baseKin;
  for (let age = 0; age < count; age++) {
    const year = birthYear + age;
    const d = getKinData(kin);
    let label = '';
    if (kin === 95) label = '極性拡張';
    else if (KYOKUSEI_KINS.has(kin)) label = '極性';
    else if (KAKUCHO_KINS.has(kin)) label = '拡張';
    rows.push({ age, year, kin, ...d, label });
    let next = kin + 105;
    if (next > 260) next -= 260;
    kin = next;
  }
  return rows;
}

export { calcKin, getKinData, getNenpyoRows, harmonicGroup, toneRelations, calcAge, TZOLKIN, KINDATE, SEAL_NAMES };
